// Bundled DNYV Certificate of Verification template (self-hosted fonts),
// base64-encoded so the serverless function needs no filesystem access.
// Source: dnyv/idcard/certificate-template.html. Tokens filled by api/_certificate.js.

export const CERT_TEMPLATE_B64 = "";
export const certTemplate = () => Buffer.from(CERT_TEMPLATE_B64, "base64").toString("utf8");
